ALTER TABLE public.business_software_customers ADD COLUMN IF NOT EXISTS company_name text;
-- An unset enquiry source is NULL, never a fabricated Other source. Existing rows are unchanged.
ALTER TABLE public.business_software_jobs ALTER COLUMN enquiry_source DROP NOT NULL;
ALTER TABLE public.business_software_jobs ALTER COLUMN enquiry_source DROP DEFAULT;
-- Create job: store the fields the New Job screen collects (title, notes, enquiry source, site address 2 and city, customer reference).
-- Backward compatible: the old keys 'source' and 'jobNotes' still work; the screen's keys 'enquirySource' and 'internalNotes' are now also read.
CREATE OR REPLACE FUNCTION public.bms_create_job(p_tenant uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); cid uuid; jid uuid; seq int; ref text; prefix text; begin
 if uid is null or not exists(select 1 from business_software_users where tenant_id=p_tenant and auth_user_id=uid and status='active') then raise exception 'not authorised'; end if;
 cid:=nullif(p_data->>'existingCustomerId','')::uuid;
 if cid is not null and not exists(select 1 from business_software_customers where id=cid and tenant_id=p_tenant) then raise exception 'customer not found in this tenant'; end if;
 if cid is null then insert into business_software_customers(tenant_id,first_name,last_name,company_name,phone,email,address_line_1,address_line_2,city,postcode) values(p_tenant,nullif(p_data->>'firstName',''),nullif(p_data->>'lastName',''),nullif(p_data->>'companyName',''),nullif(p_data->>'phone',''),nullif(p_data->>'email',''),nullif(p_data->>'addressLine1',''),nullif(p_data->>'addressLine2',''),nullif(p_data->>'city',''),nullif(p_data->>'postcode','')) returning id into cid; end if;
 if nullif(p_data->>'historicalSequenceNumber','') is not null then seq:=(p_data->>'historicalSequenceNumber')::int; else select coalesce(max(sequence_number),0)+1 into seq from business_software_jobs where tenant_id=p_tenant; end if;
 select coalesce(nullif(app_config->>'jobPrefix',''),'JOB') into prefix from business_software_tenant_settings where tenant_id=p_tenant;
 ref:=coalesce(prefix,'JOB')||lpad(seq::text,3,'0');
 insert into business_software_jobs(tenant_id,sequence_number,reference,customer_id,site_address_line_1,site_address_line_2,site_city,site_postcode,job_title,customer_reference,job_type,job_types,status,manager,enquiry_source,finishes,colour,dimensions,material,customer_requirements,internal_notes,site_visit_required,preliminary_estimate,quoted_amount,payment_method,next_action,next_action_at,next_action_assignee,scheduled_at)
 values(p_tenant,seq,ref,cid,nullif(p_data->>'siteAddressLine1',''),nullif(p_data->>'siteAddressLine2',''),nullif(p_data->>'siteCity',''),nullif(p_data->>'sitePostcode',''),nullif(p_data->>'jobTitle',''),nullif(p_data->>'customerReference',''),coalesce(nullif(p_data->>'jobType',''),'Other'),coalesce(array(select jsonb_array_elements_text(coalesce(p_data->'jobTypes','[]'::jsonb))),array[]::text[]),coalesce(nullif(p_data->>'status',''),'new_enquiry'),nullif(p_data->>'manager',''),coalesce(nullif(p_data->>'source',''),nullif(p_data->>'enquirySource','')),coalesce(array(select jsonb_array_elements_text(coalesce(p_data->'finishes','[]'::jsonb))),array[]::text[]),nullif(p_data->>'colour',''),nullif(p_data->>'dimensions',''),nullif(p_data->>'material',''),nullif(p_data->>'customerRequirements',''),coalesce(nullif(p_data->>'jobNotes',''),nullif(p_data->>'internalNotes','')),coalesce((p_data->>'siteVisitRequired')::boolean,false),nullif(p_data->>'preliminaryEstimate','')::numeric,nullif(p_data->>'quotedAmount','')::numeric,nullif(p_data->>'paymentMethod',''),nullif(p_data->>'nextAction',''),nullif(p_data->>'nextActionAt','')::timestamptz,nullif(p_data->>'nextActionAssignee',''),nullif(p_data->>'scheduledAt','')::timestamptz) returning id into jid;
 return jsonb_build_object('job',jsonb_build_object('id',jid,'reference',ref,'sequenceNumber',seq)); end
$function$;

-- Extend the existing customer update contract, preserving all prior fields and behavior.
CREATE OR REPLACE FUNCTION public.bms_patch_job(p_tenant uuid, p_reference text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); jid uuid; cid uuid; j jsonb:=coalesce(p_data->'job','{}'::jsonb); c jsonb:=coalesce(p_data->'customer','{}'::jsonb); oldj jsonb; oldc jsonb; out jsonb; actor_name text; k text; oldv jsonb; newv jsonb; label text; explicit_next boolean:=coalesce((p_data->>'explicit_next_action')::boolean,false); explicit_next_at boolean:=coalesce((p_data->>'explicit_next_action_at')::boolean,false);
begin
 if uid is null or not exists(select 1 from business_software_users where tenant_id=p_tenant and auth_user_id=uid and status='active') then raise exception 'not authorised'; end if;
 select x.id,x.customer_id,to_jsonb(x) into jid,cid,oldj from business_software_jobs x where x.tenant_id=p_tenant and upper(x.reference)=upper(p_reference); if jid is null then raise exception 'job not found'; end if;
 select to_jsonb(x) into oldc from business_software_customers x where x.id=cid and x.tenant_id=p_tenant;
 select coalesce(nullif(display_name,''),email,'CRM user') into actor_name from business_software_users where tenant_id=p_tenant and auth_user_id=uid and status='active' limit 1;
 if c<>'{}'::jsonb then update business_software_customers set company_name=case when c?'company_name' then nullif(c->>'company_name','') else company_name end,first_name=case when c?'first_name' then c->>'first_name' else first_name end,last_name=case when c?'last_name' then c->>'last_name' else last_name end,phone=case when c?'phone' then c->>'phone' else phone end,email=case when c?'email' then c->>'email' else email end,address_line_1=case when c?'address_line_1' then c->>'address_line_1' else address_line_1 end,address_line_2=case when c?'address_line_2' then c->>'address_line_2' else address_line_2 end,city=case when c?'city' then c->>'city' else city end,postcode=case when c?'postcode' then c->>'postcode' else postcode end,updated_at=now() where id=cid and tenant_id=p_tenant; end if;
 if j<>'{}'::jsonb then update business_software_jobs set status=case when j?'status' then j->>'status' else status end,manager=case when j?'manager' then nullif(j->>'manager','') else manager end,enquiry_source=case when j?'enquiry_source' then nullif(j->>'enquiry_source','') else enquiry_source end,job_type=case when j?'job_type' then nullif(j->>'job_type','') else job_type end,job_types=case when j?'job_types' then array(select jsonb_array_elements_text(j->'job_types')) else job_types end,finishes=case when j?'finishes' then array(select jsonb_array_elements_text(j->'finishes')) else finishes end,colour=case when j?'colour' then nullif(j->>'colour','') else colour end,dimensions=case when j?'dimensions' then nullif(j->>'dimensions','') else dimensions end,material=case when j?'material' then nullif(j->>'material','') else material end,customer_requirements=case when j?'customer_requirements' then nullif(j->>'customer_requirements','') else customer_requirements end,internal_notes=case when j?'internal_notes' then nullif(j->>'internal_notes','') else internal_notes end,site_visit_required=case when j?'site_visit_required' then (j->>'site_visit_required')::boolean else site_visit_required end,site_visit_at=case when j?'site_visit_at' then nullif(j->>'site_visit_at','')::timestamptz else site_visit_at end,site_visit_completed_at=case when j?'site_visit_completed_at' then nullif(j->>'site_visit_completed_at','')::timestamptz else site_visit_completed_at end,site_visit_status=case when j?'site_visit_status' then nullif(j->>'site_visit_status','') else site_visit_status end,site_visit_attendee=case when j?'site_visit_attendee' then nullif(j->>'site_visit_attendee','') else site_visit_attendee end,site_visit_notes=case when j?'site_visit_notes' then nullif(j->>'site_visit_notes','') else site_visit_notes end,site_visit_measurements=case when j?'site_visit_measurements' then nullif(j->>'site_visit_measurements','') else site_visit_measurements end,preliminary_estimate=case when j?'preliminary_estimate' then nullif(j->>'preliminary_estimate','')::numeric else preliminary_estimate end,quoted_amount=case when j?'quoted_amount' then nullif(j->>'quoted_amount','')::numeric else quoted_amount end,payment_method=case when j?'payment_method' then nullif(j->>'payment_method','') else payment_method end,next_action=case when j?'next_action' then nullif(j->>'next_action','') else next_action end,next_action_at=case when j?'next_action_at' then nullif(j->>'next_action_at','')::timestamptz else next_action_at end,next_action_assignee=case when j?'next_action_assignee' then nullif(j->>'next_action_assignee','') else next_action_assignee end,scheduled_at=case when j?'scheduled_at' then nullif(j->>'scheduled_at','')::timestamptz else scheduled_at end,expected_completion_at=case when j?'expected_completion_at' then nullif(j->>'expected_completion_at','')::timestamptz else expected_completion_at end,completed_at=case when j?'completed_at' then nullif(j->>'completed_at','')::timestamptz else completed_at end,materials_ordered=case when j?'materials_ordered' then (j->>'materials_ordered')::boolean else materials_ordered end,customer_reference=case when j?'customer_reference' then nullif(j->>'customer_reference','') else customer_reference end,snagging_required=case when j?'snagging_required' then (j->>'snagging_required')::boolean else snagging_required end,snagging_notes=case when j?'snagging_notes' then nullif(j->>'snagging_notes','') else snagging_notes end,snagging_completed_at=case when j?'snagging_completed_at' then nullif(j->>'snagging_completed_at','')::timestamptz else snagging_completed_at end,site_address_line_1=case when j?'site_address_line_1' then nullif(j->>'site_address_line_1','') else site_address_line_1 end,site_address_line_2=case when j?'site_address_line_2' then nullif(j->>'site_address_line_2','') else site_address_line_2 end,site_city=case when j?'site_city' then nullif(j->>'site_city','') else site_city end,site_postcode=case when j?'site_postcode' then nullif(j->>'site_postcode','') else site_postcode end,quantity=case when j?'quantity' then nullif(j->>'quantity','')::integer else quantity end,automation_details=case when j?'automation_details' then nullif(j->>'automation_details','') else automation_details end,locks_hardware=case when j?'locks_hardware' then nullif(j->>'locks_hardware','') else locks_hardware end,access_notes=case when j?'access_notes' then nullif(j->>'access_notes','') else access_notes end,parking_notes=case when j?'parking_notes' then nullif(j->>'parking_notes','') else parking_notes end,removal_disposal=case when j?'removal_disposal' then nullif(j->>'removal_disposal','') else removal_disposal end,making_good=case when j?'making_good' then nullif(j->>'making_good','') else making_good end,updated_at=now() where id=jid and tenant_id=p_tenant returning to_jsonb(business_software_jobs.*) into out; end if;
 for k in select jsonb_object_keys(j) loop if k='updated_at' then continue; end if; oldv:=oldj->k; newv:=coalesce(out,oldj)->k; if oldv is distinct from newv then if (k='next_action' and not explicit_next) or (k='next_action_at' and not explicit_next_at) then continue; end if; label:=case k when 'status' then 'status' when 'next_action' then 'next action' when 'next_action_at' then 'next action date' when 'manager' then 'assigned to' when 'job_types' then 'work type' when 'job_type' then 'work type' when 'preliminary_estimate' then 'estimate' when 'quoted_amount' then 'quoted amount' else replace(k,'_',' ') end; if k='job_type' and j?'job_types' then continue; end if; insert into business_software_activities(tenant_id,job_id,activity_type,actor,summary,details,occurred_at) values(p_tenant,jid,case when k='status' then 'status' else 'edit' end,actor_name,actor_name||' changed '||label||case when k in ('status','next_action','manager') then ' to '||replace(coalesce(nullif((coalesce(out,oldj))->>k,''),'none'),'_',' ') when k='job_types' then ' to '||coalesce(nullif(array_to_string(array(select jsonb_array_elements_text((coalesce(out,oldj))->'job_types')),', '),''),'none') else '' end,case when k='status' then 'From '||replace(coalesce(oldj->>k,'none'),'_',' ')||' to '||replace(coalesce((coalesce(out,oldj))->>k,'none'),'_',' ') when k='next_action' then 'From '||coalesce(oldj->>k,'none')||' to '||coalesce((coalesce(out,oldj))->>k,'none') else 'Updated '||label end,now()); end if; end loop;
 for k in select jsonb_object_keys(c) loop oldv:=oldc->k; select to_jsonb(x)->k into newv from business_software_customers x where x.id=cid and x.tenant_id=p_tenant; if oldv is distinct from newv then label:='customer '||replace(k,'_',' '); insert into business_software_activities(tenant_id,job_id,activity_type,actor,summary,details,occurred_at) values(p_tenant,jid,'edit',actor_name,actor_name||' changed '||label,'Updated '||label,now()); end if; end loop;
 return jsonb_build_object('job',coalesce(out,(select to_jsonb(x) from business_software_jobs x where x.id=jid)),'customer',(select to_jsonb(x) from business_software_customers x where x.id=cid));
end $function$
;

-- Include the optional business label in the existing customer list contract.
CREATE OR REPLACE FUNCTION public.bms_customers_payload(p_tenant uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select coalesce(jsonb_agg(jsonb_build_object('id',id,'firstName',first_name,'lastName',last_name,'companyName',company_name,'phone',phone,'email',email,'addressLine1',address_line_1,'addressLine2',address_line_2,'city',city,'postcode',postcode) order by first_name,last_name),'[]'::jsonb) from business_software_customers where tenant_id=p_tenant $function$
;
